54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    /** Syntactic email check: a non-empty local part, an '@', and a dotted domain, none containing spaces. */
60	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
61	
62	    private final ClinicService clinicService;
63	
64	    private final OwnerMapper ownerMapper;
65	
66	    private final PetMapper petMapper;
67	
68	    private final VisitMapper visitMapper;
69	
70	    public OwnerRestControllerV1(ClinicService clinicService,
71	                                 OwnerMapper ownerMapper,
72	                                 PetMapper petMapper,
73	                                 VisitMapper visitMapper) {
74	        this.clinicService = clinicService;
75	        this.ownerMapper = ownerMapper;
76	        this.petMapper = petMapper;
77	        this.visitMapper = visitMapper;
78	    }
79	
80	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
81	    @Override
82	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
83	        Collection<Owner> owners;
84	        if (lastName != null) {
85	            owners = this.clinicService.findOwnerByLastName(lastName);
86	        } else {
87	            owners = this.clinicService.findAllOwners();
88	        }
89	        if (owners.isEmpty()) {
90	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
91	        }
92	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
93	    }
94	
95	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
96	    @Override
97	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
98	        Owner owner = this.clinicService.findOwnerById(ownerId);
99	        if (owner == null) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
108	        HttpHeaders headers = new HttpHeaders();
109	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
110	        if (owner.getEmail() != null) {
111	            String email = owner.getEmail().trim().toLowerCase(Locale.ROOT);
112	            if (!EMAIL_PATTERN.matcher(email).matches()) {
113	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
114	            }
115	            owner.setEmail(email);
116	        }
117	        String telephone = normalizeTelephone(owner.getTelephone());
118	        if (telephone == null) {
119	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
120	        }
121	        owner.setTelephone(telephone);
122	        if (owner.getRegistrationDate() == null) {
123	            owner.setRegistrationDate(LocalDate.now());
124	        }
125	        if (isTelephoneInUse(telephone)) {
126	            return new ResponseEntity<>(HttpStatus.CONFLICT);
127	        }
128	        owner.setCustomerCode(generateCustomerCode(owner.getLastName()));
129	        this.clinicService.saveOwner(owner);
130	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
131	        headers.setLocation(UriComponentsBuilder.newInstance()
132	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
133	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Override
138	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
139	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
140	        if (currentOwner == null) {
141	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
142	        }
143	        currentOwner.setAddress(ownerFieldsDto.getAddress());
144	        currentOwner.setCity(ownerFieldsDto.getCity());
145	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
146	        currentOwner.setLastName(ownerFieldsDto.getLastName());
147	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
148	        String email = ownerFieldsDto.getEmail();
149	        if (email != null) {
150	            email = email.trim().toLowerCase(Locale.ROOT);
151	            if (!EMAIL_PATTERN.matcher(email).matches()) {
152	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
153	            }
154	        }
155	        currentOwner.setEmail(email);
156	        this.clinicService.saveOwner(currentOwner);
157	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
158	    }
159	
160	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
161	    @Transactional
162	    @Override
163	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
164	        Owner owner = this.clinicService.findOwnerById(ownerId);
165	        if (owner == null) {
166	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
167	        }
168	        this.clinicService.deleteOwner(owner);
169	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
170	    }
171	
172	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
173	    @Override
174	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
175	        Owner owner = this.clinicService.findOwnerById(ownerId);
176	        if (owner == null) {
177	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
178	        }
179	        HttpHeaders headers = new HttpHeaders();
180	        Pet pet = petMapper.toPet(petFieldsDto);
181	        owner.setId(ownerId);
182	        pet.setOwner(owner);
183	        pet.getType().setName(null);
184	        this.clinicService.savePet(pet);
185	        PetDto petDto = petMapper.toPetDto(pet);
186	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
187	            .buildAndExpand(pet.getId()).toUri());
188	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
189	    }
190	
191	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
192	    @Override
193	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
194	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
195	        if (currentOwner != null) {
196	            Pet currentPet = this.clinicService.findPetById(petId);
197	            if (currentPet != null) {
198	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
199	                currentPet.setName(petFieldsDto.getName());
200	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
201	                this.clinicService.savePet(currentPet);
202	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
203	            }
204	        }
205	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
206	    }
207	
208	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
209	    @Override
210	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
211	        HttpHeaders headers = new HttpHeaders();
212	        Visit visit = visitMapper.toVisit(visitFieldsDto);
213	        Pet pet = new Pet();
214	        pet.setId(petId);
215	        visit.setPet(pet);
216	        this.clinicService.saveVisit(visit);
217	        VisitDto visitDto = visitMapper.toVisitDto(visit);
218	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
219	            .buildAndExpand(visit.getId()).toUri());
220	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
221	    }
222	
223	
224	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
225	    @Override
226	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
227	        Owner owner = this.clinicService.findOwnerById(ownerId);
228	        if (owner != null) {
229	            Pet pet = owner.getPet(petId);
230	            if (pet != null) {
231	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
232	            }
233	        }
234	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
235	    }
236	
237	    /** Matches a well-formed E.164 number: a '+' followed by 8 to 15 digits. */
238	    private static final Pattern E164_PATTERN = Pattern.compile("^\\+[0-9]{8,15}$");
239	
240	    /**
241	     * Canonical stored form of a telephone number in E.164: a leading '+' and country
242	     * code are kept when present; otherwise country code '+61' is assumed and a single
243	     * leading '0' is dropped from the national digits. Spaces, dashes and brackets are
244	     * stripped. The result must be a '+' followed by 8 to 15 digits.
245	     * Returns {@code null} when the number cannot form a valid E.164 value.
246	     */
247	    private static String normalizeTelephone(String telephone) {
248	        if (telephone == null) {
249	            return null;
250	        }
251	        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
252	        String e164;
253	        if (cleaned.startsWith("+")) {
254	            e164 = cleaned;
255	        } else {
256	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
257	            e164 = "+61" + national;
258	        }
259	        return E164_PATTERN.matcher(e164).matches() ? e164 : null;
260	    }
261	
262	    /**
263	     * Build the customer code '<LAST3>-<NNNN>': LAST3 is the upper-cased first three letters
264	     * of {@code lastName} and NNNN is a global 4-digit zero-padded sequence equal to one more
265	     * than the current number of owners (e.g. 'SMI-0007').
266	     */
267	    private String generateCustomerCode(String lastName) {
268	        String letters = lastName.replaceAll("[^\\p{L}]", "");
269	        String last3 = letters.substring(0, Math.min(3, letters.length())).toUpperCase(Locale.ROOT);
270	        int sequence = this.clinicService.findAllOwners().size() + 1;
271	        return String.format("%s-%04d", last3, sequence);
272	    }
273	
274	    /** Whether any existing owner already uses the given (E.164) telephone number. */
275	    private boolean isTelephoneInUse(String telephone) {
276	        return this.clinicService.findAllOwners().stream()
277	            .map(Owner::getTelephone)
278	            .filter(existing -> existing != null)
279	            .map(OwnerRestControllerV1::normalizeTelephone)
280	            .filter(existing -> existing != null)
281	            .anyMatch(telephone::equals);
282	    }
283	}
